def _rules(doc_lang: str) -> str:
    lang = "Documentation/Devlog **Russian**, code/commits **English**." if doc_lang == "ru" else "All documentation **English**."
    return _RULES_BODY.format(lang=lang)




def _gen_rule(title: str, p: str, s: str, l: str = "ru", extra_header: str = "", tail: str = "") -> str:
    st = STACK_PRESETS.get(s, STACK_PRESETS["generic"])
    lang_desc = "Russian (docs), English (code)" if l == "ru" else "English"
    build_cmd = st.get("build_cmd", "")
    build_line = f"- **Build:** `{build_cmd}`\n" if build_cmd else ""
    return (
        f"# {title} for {p}\n\n"
        f"> **Stack:** {st['name']} | **Language:** {lang_desc}{extra_header}\n"
        f"> **Canonical Standard (SSOT):** [[AGENTS.md]] | **KB Index:** [[docs/00_Index|00_Index]]\n\n"
        f"## ⚡ Stack Verification Commands\n"
        f"{build_line}"
        f"- **Test:** `{st['test_cmd']}`\n"
        f"- **Lint:** `python3 scripts/kb_lint.py --path docs`\n\n"
        f"## 🛡️ Operating Rules & Routing\n"
        f"1. **Single Source of Truth & Zero Round-Trip:** Read `AGENTS.md` at session start. For Modes 0-3, execute directly from hot prefix without reading SKILL.md; co-fetch context in parallel.\n"
        f"2. **Read-Only Invariant & Human Guardrails:** Modes 1 (`/kb-plan`), 2 (`/kb-task`), 2B (`/kb-bug`), 2C (`/kb-triage`): STRICTLY NO CODE CHANGES. Guide user with friendly next steps rather than blocking errors.\n"
        f"3. **Fast-Track Protocol:** Micro-tasks (≤ 30 LOC, ≤ 2 files) bypass Mode 1 planning via `/kb-task --fast` using Micro-Spec.\n"
        f"4. **Mode 3 Implementation:** `/kb-implement <TASK-XXX | BUG-XXX>` authorizes work strictly on ONE target. Execute TDD for bugs (RED -> GREEN -> REFACTOR). Run verification commands before completion.\n"
        f"5. **Anti-Echo & Single-Task Barrier:** Never reprint full files in chat responses. Stop tool calls upon task completion (Stop & Yield).\n"
        f"6. **Quality Gates:** Tier 1 (Enforce: tests/lint) > Tier 2 (Always-On: AGENTS.md) > Tier 3 (Playbook: skills). Never rely on Tier 3 for critical rules.\n"
        f"7. **The 4-State UI & Visual Verification:** Design 4 UI states (Empty/Loading/Error/Populated); store screenshots in `docs/assets/screenshots/<target>/` (or Headless fallback); isolate test snapshots in `tmp/ui_snapshots/`.\n"
        f"{tail}"
    )


